  opaque predicate Left(a: int, b: int, u: int) { a <= u <= b }
  opaque predicate Right(c: int, d: int, v: int) { c <= v <= d }
  opaque predicate Offset(gap: int, u: int, v: int) { 0 < gap && v == u + gap }
